    ('growth-and-development', 3, 'Brooks manages growth through forward planning rather than either growth caps or wholesale deregulation. At the May 12, 2021 State of the City she personally presented Tualatin 2040, the city''s long-range vision including "updates to the comprehensive plan and development code focusing on providing a diversity of housing and a climate action plan" — planning frameworks that shape where and how the nearly built-out city grows. She voted February 28, 2022 to approve the Tualatin Heights infill density increase, showing she supports accommodating growth within existing city fabric. At the same time, on the Basalt Creek growth area she insisted the supporting infrastructure be done right, opposing right-of-way funding for the parkway extension in February 2021 until flooding, stormwater, and environmental problems with "managing the road buildout" were addressed. That combination — proactive comprehensive planning plus insisting infrastructure issues be resolved as expansion proceeds — matches the plan-proactively chair, with no documented support for growth moratoria, voter-approval requirements, or removing regulatory oversight.', ARRAY['https://tualatinlife.com/featured/state-of-the-city-busy/', 'https://tualatinlife.com/featured/basalt-creek-parkway-plan-raises-questions/', 'https://tualatinlife.com/local-news/tualatin-heights-re-zoning-passes-city-council-in-second-vote/']::text[])
)
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT 'f0f26baf-1de7-408d-8073-219ad6236dc7'::uuid, ct.id, s.reasoning, s.sources
FROM s JOIN inform.compass_topics ct ON ct.topic_key = s.topic_key AND ct.is_live = true
ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning = EXCLUDED.reasoning, sources = EXCLUDED.sources;

DO $$
DECLARE n INTEGER;
        v_ext BIGINT;
BEGIN
  -- Identity gate (WR-01): the hardcoded politician UUID must belong to the
  -- intended official's external_id — a wrong-but-existing UUID would satisfy
  -- the FK and the count gate below while silently misattributing stances.
  SELECT external_id INTO v_ext FROM essentials.politicians WHERE id = 'f0f26baf-1de7-408d-8073-219ad6236dc7';
  IF v_ext IS DISTINCT FROM -4174954 THEN
    RAISE EXCEPTION 'UUID f0f26baf-1de7-408d-8073-219ad6236dc7 does not belong to external_id -4174954 (Bridget Brooks) — found %', v_ext;
  END IF;
  SELECT COUNT(*) INTO n FROM inform.politician_answers WHERE politician_id = 'f0f26baf-1de7-408d-8073-219ad6236dc7';
  IF n <> 9 THEN
    RAISE EXCEPTION 'Expected % answers, found % — topic_key mismatch dropped rows', 9, n;
  END IF;
  -- Context-parity gate (WR-03): the context VALUES list is a verbatim
  -- duplicate of the answers list; count it too so a single-sided edit
  -- cannot silently drop or skew reasoning/sources rows.
  SELECT COUNT(*) INTO n FROM inform.politician_context WHERE politician_id = 'f0f26baf-1de7-408d-8073-219ad6236dc7';
  IF n <> 9 THEN
    RAISE EXCEPTION 'Expected % context rows, found % — answers/context VALUES lists diverged', 9, n;
  END IF;
END $$;

COMMIT;
